/*!
 * fengshui-annual.js  (reference implementation, no dependencies, ES2015)
 * - Sun apparent ecliptic longitude (VSOP87D Earth, truncated; nutation; aberration; DeltaT)
 * - 24 solar terms / 12 "jie" (month boundaries) instants, UTC+8 output helper
 * - Ganzhi year (Lichun boundary) / ganzhi month (jie boundary, Five-Tiger rule)
 * - Annual & monthly flying-star center, Luoshu forward flight, Nine-Yun position
 * - Taisui / Suipo / Sansha / Wuhuang / Erhei direction helpers
 * All "instants" are milliseconds since Unix epoch (UTC). Bearings are degrees clockwise from true north.
 */
(function (root, factory) {
  if (typeof module === 'object' && module.exports) module.exports = factory();
  else root.FengshuiAnnual = factory();
})(typeof self !== 'undefined' ? self : this, function () {
  'use strict';

  var STEMS = '甲乙丙丁戊己庚辛壬癸'.split('');
  var BRANCHES = '子丑寅卯辰巳午未申酉戌亥'.split('');
  // index i -> apparent solar longitude (285 + 15*i) mod 360 ; even i = jie (month start), odd i = zhongqi
  var TERM_NAMES = ['小寒','大寒','立春','雨水','驚蟄','春分','清明','穀雨','立夏','小滿','芒種','夏至',
                    '小暑','大暑','立秋','處暑','白露','秋分','寒露','霜降','立冬','小雪','大雪','冬至'];
  var D2R = Math.PI / 180;

  // ---- VSOP87D Earth heliocentric longitude, terms [A, B, C] : A*cos(B + C*T), T in Julian millennia (TDB) ----
  // Truncated to A*0.1^k >= 1e-6 rad (covers 1900-2100). Source: IMCCE VSOP87D.ear (Bretagnon & Francou 1988)
  var VSOP_L = [
    // T^0 (33 terms)
    [[1.75347046,0,0],[0.03341656,4.66926,6283.07585],[0.00034894,4.6261,12566.1517],[0.00003418,2.82887,3.52312],[0.00003497,2.74412,5753.38488],[0.00003136,3.62767,77713.77147],[0.00002676,4.41808,7860.41939],[0.00002343,6.13516,3930.2097],[0.00001273,2.0371,529.69097],[0.00001324,0.74246,11506.76977],[0.00000902,2.04505,26.29832],[0.00001199,1.10963,1577.34354],[0.00000857,3.50849,398.149],[0.0000078,1.17883,5223.69392],[0.0000099,5.23268,5884.92685],[0.00000753,2.53339,5507.55324],[0.00000505,4.58293,18849.22755],[0.00000492,4.20507,775.52261],[0.00000357,2.91954,0.06731],[0.00000284,1.89869,796.29801],[0.00000243,0.34481,5486.77784],[0.00000317,5.84902,11790.62909],[0.00000271,0.31489,10977.0788],[0.00000206,4.80647,2544.31442],[0.00000205,1.86948,5573.1428],[0.00000202,2.45768,6069.77675],[0.00000126,1.08303,20.7754],[0.00000156,0.83306,213.2991],[0.00000115,0.64545,0.98032],[0.00000103,0.636,4694.00295],[0.00000102,4.2668,7.11355],[0.00000132,3.41118,2942.46342],[0.00000102,0.97569,15720.83878]],
    // T^1 (3 terms)
    [[6283.31966747,0,0],[0.00206059,2.67823,6283.07585],[0.00004303,2.63513,12566.1517]],
    // T^2 (1 terms)
    [[0.00052919,0,0]]
  ];
  // Earth-Sun distance (AU), only needed for the aberration term (-20.4898"/R)
  var VSOP_R0 = [[1.00013989,0,0],[0.016707,3.09846,6283.07585],[0.00013956,3.05525,12566.1517]];

  // DeltaT = TT - UT in seconds; Espenak & Meeus polynomials (NASA), valid 1900-2150 (y = decimal year)
  function deltaT(y) {
    var t;
    if (y < 1900) y = 1900;                            // clamp (only used for look-behind into Dec 1899; < 5 s effect)
    if (y < 1920) { t = y - 1900; return -2.79 + 1.494119 * t - 0.0598939 * t * t + 0.0061966 * Math.pow(t, 3) - 0.000197 * Math.pow(t, 4); }
    if (y < 1941) { t = y - 1920; return 21.20 + 0.84493 * t - 0.076100 * t * t + 0.0020936 * Math.pow(t, 3); }
    if (y < 1961) { t = y - 1950; return 29.07 + 0.407 * t - t * t / 233 + Math.pow(t, 3) / 2547; }
    if (y < 1986) { t = y - 1975; return 45.45 + 1.067 * t - t * t / 260 - Math.pow(t, 3) / 718; }
    if (y < 2005) { t = y - 2000; return 63.86 + 0.3345 * t - 0.060374 * t * t + 0.0017275 * Math.pow(t, 3) + 0.000651814 * Math.pow(t, 4) + 0.00002373599 * Math.pow(t, 5); }
    if (y < 2050) { t = y - 2000; return 62.92 + 0.32217 * t + 0.005589 * t * t; }
    if (y <= 2150) return -20 + 32 * Math.pow((y - 1820) / 100, 2) - 0.5628 * (2150 - y);
    throw new RangeError('year > 2150 not supported');
  }

  function series(tab, T) {           // sum_k T^k * sum_j A cos(B + C T)
    var total = 0, tk = 1, k, j, s, row;
    for (k = 0; k < tab.length; k++) {
      row = tab[k]; s = 0;
      for (j = 0; j < row.length; j++) s += row[j][0] * Math.cos(row[j][1] + row[j][2] * T);
      total += s * tk; tk *= T;
    }
    return total;
  }

  // Apparent geocentric ecliptic longitude of the Sun (degrees, true equinox of date), input = JD in UT
  function sunApparentLongitude(jdUT) {
    var jde = jdUT + deltaT(2000 + (jdUT - 2451545) / 365.25) / 86400;
    var T = (jde - 2451545) / 365250;                 // millennia
    var Tc = (jde - 2451545) / 36525;                 // centuries
    var lon = series(VSOP_L, T) / D2R + 180;          // geometric, mean equinox of date
    var R = series([VSOP_R0], T);
    var om = (125.04452 - 1934.136261 * Tc) * D2R;    // nutation in longitude (Meeus ch.22, 4 terms, ~0.05")
    var ls = (280.4665 + 36000.7698 * Tc) * D2R;
    var lm = (218.3165 + 481267.8813 * Tc) * D2R;
    var dpsi = (-17.20 * Math.sin(om) - 1.32 * Math.sin(2 * ls) - 0.23 * Math.sin(2 * lm) + 0.21 * Math.sin(2 * om)) / 3600;
    lon += dpsi - 20.4898 / R / 3600;                 // nutation + annual aberration
    return ((lon % 360) + 360) % 360;
  }

  var _cache = {};
  // Instant (ms, UTC) at which the Sun reaches longitude (285 + 15*i) mod 360 in calendar year `year` (UTC year, Jan..Dec)
  function termInstant(year, i) {
    var key = year * 100 + i;
    if (_cache[key] !== undefined) return _cache[key];
    var target = (285 + 15 * i) % 360;
    var jd = Date.UTC(year, 0, 1) / 86400000 + 2440587.5 + ((target - 280 + 360) % 360) / 0.9856;
    for (var n = 0; n < 20; n++) {                     // Newton with mean motion 0.9856 deg/day; 4-7 iterations to 1e-8 deg (~17 ms for 4824 terms)
      var d = ((target - sunApparentLongitude(jd) + 540) % 360) - 180;
      jd += d / 0.9856;
      if (Math.abs(d) < 1e-8) break;
    }
    return (_cache[key] = Math.round((jd - 2440587.5) * 86400000));
  }

  function pad(n) { return (n < 10 ? '0' : '') + n; }
  // 'YYYY-MM-DD HH:mm' in UTC+8 (rounded to nearest minute, like HKO / CWA / PMO publish)
  function formatCST(ms, withSeconds) {
    var t = withSeconds ? new Date(Math.round(ms / 1000) * 1000 + 8 * 3600e3) : new Date(Math.round(ms / 60000) * 60000 + 8 * 3600e3);
    var s = t.getUTCFullYear() + '-' + pad(t.getUTCMonth() + 1) + '-' + pad(t.getUTCDate()) + ' ' + pad(t.getUTCHours()) + ':' + pad(t.getUTCMinutes());
    return withSeconds ? s + ':' + pad(t.getUTCSeconds()) : s;
  }
  function lichun(year) { return termInstant(year, 2); }

  // ---------- Ganzhi ----------
  // "Feng-shui year" = ganzhi year that changes at the exact Lichun instant.
  function fengshuiYear(ms) {
    var y = new Date(ms).getUTCFullYear();
    return ms >= lichun(y) ? y : y - 1;
  }
  function yearGanzhi(fy) {
    var idx = (((fy - 4) % 60) + 60) % 60;
    return { index: idx, stem: idx % 10, branch: idx % 12, name: STEMS[idx % 10] + BRANCHES[idx % 12] };
  }
  // Month = interval between two consecutive jie (even term indices). Returns the interval containing ms.
  function monthOf(ms) {
    var y = new Date(ms).getUTCFullYear(), best = null, yy, i, t;
    for (yy = y - 1; yy <= y + 1; yy++) for (i = 0; i < 24; i += 2) {
      t = termInstant(yy, i);
      if (t <= ms && (best === null || t > best.start)) best = { start: t, year: yy, jie: i };
    }
    // end = next jie
    var j = best.jie + 2, ey = best.year;
    if (j >= 24) { j = 0; ey++; }
    var branch = (best.jie / 2 + 1) % 12;              // 小寒->丑(1) ... 立春->寅(2) ... 大雪->子(0)
    var order = (branch - 2 + 12) % 12;                // 0 = 寅月 ... 11 = 丑月
    var fy = fengshuiYear(ms), ys = yearGanzhi(fy).stem;
    var stem = (2 * ys + 2 + order) % 10;              // Five-Tiger rule: 寅月 stem = 2*yearStem + 2 (mod 10)
    return { jieName: TERM_NAMES[best.jie], start: best.start, end: termInstant(ey, j),
             branch: branch, order: order, stem: stem, name: STEMS[stem] + BRANCHES[branch] };
  }

  // ---------- Flying stars ----------
  function wrap9(n) { n = ((n % 9) + 9) % 9; return n === 0 ? 9 : n; }
  // Annual center star of feng-shui year fy. Anchor: 1864 (Upper Yuan jiazi) = 1, decreasing by 1 per year.
  function annualCenter(fy) { return wrap9(1 - (fy - 1864)); }
  // Monthly center star. first-month (寅) star by year branch group, then -1 per month (order 0..11).
  function monthlyCenter(yearBranch, order) {
    // 子午卯酉(0,3,6,9)->8 ; 丑辰未戌(1,4,7,10)->5 ; 寅巳申亥(2,5,8,11)->2  ==  [8,5,2][branch % 3]
    return wrap9([8, 5, 2][yearBranch % 3] - order);
  }
  // Luoshu forward flight order of palaces: center, 乾NW, 兌W, 艮NE, 離S, 坎N, 坤SW, 震E, 巽SE
  var PALACES = [
    { gua: '中', dir: '中宮', bearing: null }, { gua: '乾', dir: '西北', bearing: 315 }, { gua: '兌', dir: '西', bearing: 270 },
    { gua: '艮', dir: '東北', bearing: 45 }, { gua: '離', dir: '南', bearing: 180 }, { gua: '坎', dir: '北', bearing: 0 },
    { gua: '坤', dir: '西南', bearing: 225 }, { gua: '震', dir: '東', bearing: 90 }, { gua: '巽', dir: '東南', bearing: 135 }
  ];
  function fly(center) {                                // -> { '中宮': c, '西北': c+1, ... }
    var out = {};
    for (var k = 0; k < 9; k++) out[PALACES[k].dir] = wrap9(center + k);
    return out;
  }
  function palaceOfStar(center, star) { return PALACES[((star - center) % 9 + 9) % 9].dir; }

  // ---------- Nine Yun ----------
  function nineYun(fy) {
    var d = (((fy - 1864) % 180) + 180) % 180;
    return { yun: Math.floor(d / 20) + 1, yunYear: (d % 20) + 1, yuan: d < 60 ? '上元' : (d < 120 ? '中元' : '下元') };
  }

  // ---------- Taisui / Suipo / Sansha ----------
  var SHAN24 = '壬子癸丑艮寅甲卯乙辰巽巳丙午丁未坤申庚酉辛戌乾亥'.split('');   // clockwise, 壬 centered at 345 deg
  function shanBearing(name) { return ((SHAN24.indexOf(name) - 1) * 15 + 360) % 360; }
  var SANSHA_GROUP = { 8: 0, 0: 0, 4: 0, 11: 1, 3: 1, 7: 1, 2: 2, 6: 2, 10: 2, 5: 3, 9: 3, 1: 3 };
  var SANSHA_TABLE = [   // by year-branch group: 申子辰 / 亥卯未 / 寅午戌 / 巳酉丑
    { dir: '南', jie: 5, zai: 6, sui: 7, gan: ['丙', '丁'] },   // 巳 午 未
    { dir: '西', jie: 8, zai: 9, sui: 10, gan: ['庚', '辛'] },  // 申 酉 戌
    { dir: '北', jie: 11, zai: 0, sui: 1, gan: ['壬', '癸'] },  // 亥 子 丑
    { dir: '東', jie: 2, zai: 3, sui: 4, gan: ['甲', '乙'] }    // 寅 卯 辰
  ];
  function taisui(yearBranch) {
    return { branch: BRANCHES[yearBranch], bearing: yearBranch * 30,
             suipo: BRANCHES[(yearBranch + 6) % 12], suipoBearing: ((yearBranch + 6) % 12) * 30 };
  }
  function sansha(yearBranch) {
    var g = SANSHA_TABLE[SANSHA_GROUP[yearBranch]], mid = g.zai * 30;
    return { dir: g.dir, jieSha: BRANCHES[g.jie], zaiSha: BRANCHES[g.zai], suiSha: BRANCHES[g.sui],
             jiaSha: g.gan, arcFrom: (mid - 37.5 + 360) % 360, arcTo: (mid + 37.5) % 360 };
  }

  // 12 solar-term months of feng-shui year fy: 寅月 (立春) ... 丑月 (next year's 小寒)
  function monthTable(fy) {
    var gz = yearGanzhi(fy), rows = [], order, idx, yy, start, endIdx, endYear;
    for (order = 0; order < 12; order++) {
      idx = order === 11 ? 0 : 2 + 2 * order; yy = order === 11 ? fy + 1 : fy;
      start = termInstant(yy, idx);
      endIdx = idx + 2; endYear = yy; if (endIdx >= 24) { endIdx = 0; endYear = yy + 1; }
      var branch = (order + 2) % 12, stem = (2 * gz.stem + 2 + order) % 10, c = monthlyCenter(gz.branch, order);
      rows.push({ order: order, jie: TERM_NAMES[idx], start: start, end: termInstant(endYear, endIdx),
                  ganzhi: STEMS[stem] + BRANCHES[branch], center: c, wuhuang: palaceOfStar(c, 5), erhei: palaceOfStar(c, 2) });
    }
    return rows;
  }

  // ---------- one-shot analysis ----------
  function analyze(ms) {
    var fy = fengshuiYear(ms), gz = yearGanzhi(fy), mo = monthOf(ms);
    var yc = annualCenter(fy), mc = monthlyCenter(gz.branch, mo.order);
    return { fengshuiYear: fy, yearGanzhi: gz.name, lichun: lichun(fy), month: mo, yun: nineYun(fy),
             annualCenter: yc, annualChart: fly(yc), wuhuang: palaceOfStar(yc, 5), erhei: palaceOfStar(yc, 2),
             monthlyCenter: mc, monthlyChart: fly(mc), taisui: taisui(gz.branch), sansha: sansha(gz.branch) };
  }

  return { STEMS: STEMS, BRANCHES: BRANCHES, TERM_NAMES: TERM_NAMES, PALACES: PALACES, SHAN24: SHAN24,
           deltaT: deltaT, sunApparentLongitude: sunApparentLongitude, termInstant: termInstant, formatCST: formatCST,
           lichun: lichun, fengshuiYear: fengshuiYear, yearGanzhi: yearGanzhi, monthOf: monthOf,
           annualCenter: annualCenter, monthlyCenter: monthlyCenter, fly: fly, palaceOfStar: palaceOfStar,
           nineYun: nineYun, monthTable: monthTable, taisui: taisui, sansha: sansha, shanBearing: shanBearing, analyze: analyze };
});

testRunner.source:
// Run annual.json fixtures against the reference implementation.  usage: node run_fixtures.mjs <fixtures.json> <fengshui-annual.js>
import fs from 'node:fs';
import { createRequire } from 'node:module';
const require = createRequire(import.meta.url);
const fixPath = process.argv[2] || 'annual.json';
const F = require(process.argv[3] ? (process.argv[3].startsWith('.') || process.argv[3].includes(':') ? process.argv[3] : './' + process.argv[3]) : './fengshui-annual.js');
const fx = JSON.parse(fs.readFileSync(fixPath, 'utf8'));
const cst = s => Date.parse(s.replace(' ', 'T') + ':00+08:00');
const eq = (a, b) => JSON.stringify(a) === JSON.stringify(b);
let pass = 0; const fails = [];
const byType = {};
for (const c of fx.cases) {
  let ok = false, got = null;
  const I = c.input, E = c.expected;
  try {
    switch (c.type) {
      case 'solar_term_time': {
        const ms = F.termInstant(I.year, I.termIndex);
        const dmin = (ms - Date.parse(E.utc)) / 60000;
        got = { deltaMinutes: +dmin.toFixed(3), cst: F.formatCST(ms, true) };
        ok = Math.abs(dmin) <= c.toleranceMinutes;
        break;
      }
      case 'solar_longitude_at_instant': {
        const ms = F.termInstant(I.year, I.termIndex);
        const lon = F.sunApparentLongitude(ms / 86400000 + 2440587.5);
        got = { lon }; ok = Math.abs(lon - E.apparentLongitudeDeg) <= c.toleranceDeg;
        break;
      }
      case 'fengshui_year_at': {
        const a = F.analyze(cst(I.instantCST));
        got = { fengshuiYear: a.fengshuiYear, ganzhi: a.yearGanzhi, annualCenter: a.annualCenter };
        ok = eq(got, { fengshuiYear: E.fengshuiYear, ganzhi: E.ganzhi, annualCenter: E.annualCenter });
        break;
      }
      case 'annual_center_star': {
        const y = I.fengshuiYear, n = F.nineYun(y);
        got = { center: F.annualCenter(y), ganzhi: F.yearGanzhi(y).name, yun: n.yun, yunYear: n.yunYear, yuan: n.yuan };
        ok = eq(got, { center: E.center, ganzhi: E.ganzhi, yun: E.yun, yunYear: E.yunYear, yuan: E.yuan });
        break;
      }
      case 'annual_flying_chart': {
        const c0 = F.annualCenter(I.fengshuiYear);
        got = { center: c0, chart: F.fly(c0) };
        ok = c0 === E.center && Object.keys(E.chart).every(k => got.chart[k] === E.chart[k]);
        break;
      }
      case 'wuhuang_erhei_direction': {
        const c0 = F.annualCenter(I.fengshuiYear);
        got = { center: c0, wuhuang: F.palaceOfStar(c0, 5), erhei: F.palaceOfStar(c0, 2) };
        ok = eq(got, { center: E.center, wuhuang: E.wuhuang, erhei: E.erhei });
        break;
      }
      case 'monthly_flying_star': {
        const a = F.analyze(cst(I.instantCST));
        got = { fengshuiYear: a.fengshuiYear, jie: a.month.jieName, monthGanzhi: a.month.name, monthOrder: a.month.order, monthlyCenter: a.monthlyCenter };
        ok = got.fengshuiYear === E.fengshuiYear && got.jie === E.jie && got.monthGanzhi === E.monthGanzhi && got.monthOrder === E.monthOrder && got.monthlyCenter === E.monthlyCenter;
        if (E.annualCenter !== undefined) ok = ok && a.annualCenter === E.annualCenter;
        if (E.startCST) {
          const ds = (a.month.start - cst(E.startCST)) / 60000, de = (a.month.end - cst(E.endCST)) / 60000;
          got.startDeltaMin = +ds.toFixed(2); got.endDeltaMin = +de.toFixed(2);
          ok = ok && Math.abs(ds) <= c.toleranceMinutes && Math.abs(de) <= c.toleranceMinutes;
        }
        if (E.monthlyChart) ok = ok && Object.keys(E.monthlyChart).every(k => a.monthlyChart[k] === E.monthlyChart[k]);
        if (E.wuhuang) ok = ok && a.month && F.palaceOfStar(a.monthlyCenter, 5) === E.wuhuang && F.palaceOfStar(a.monthlyCenter, 2) === E.erhei;
        break;
      }
      case 'taisui_sansha': {
        const bi = F.BRANCHES.indexOf(I.yearBranch), t = F.taisui(bi), s = F.sansha(bi);
        got = { taisuiBranch: t.branch, taisuiBearing: t.bearing, suipoBranch: t.suipo, suipoBearing: t.suipoBearing, sanshaDir: s.dir,
                sanshaMountains: s.jieSha + s.zaiSha + s.suiSha, jieSha: s.jieSha, zaiSha: s.zaiSha, suiSha: s.suiSha, jiaSha: s.jiaSha.join(''),
                sanshaArcFrom: s.arcFrom, sanshaArcTo: s.arcTo };
        ok = eq(got, E);
        break;
      }
      case 'taisui_sansha_year': {
        const y = I.fengshuiYear, gz = F.yearGanzhi(y), t = F.taisui(gz.branch), s = F.sansha(gz.branch);
        got = { ganzhi: gz.name, taisui: t.branch, suipo: t.suipo, sansha: s.jieSha + s.zaiSha + s.suiSha, sanshaDir: s.dir, jiaSha: s.jiaSha.join(''), wuhuang: F.palaceOfStar(F.annualCenter(y), 5) };
        ok = Object.keys(E).every(k => got[k] === E[k]);
        break;
      }
      case 'nine_yun_at': {
        const a = F.analyze(cst(I.instantCST));
        got = { fengshuiYear: a.fengshuiYear, yun: a.yun.yun, yunYear: a.yun.yunYear, yuan: a.yun.yuan };
        ok = eq(got, { fengshuiYear: E.fengshuiYear, yun: E.yun, yunYear: E.yunYear, yuan: E.yuan });
        break;
      }
      default: got = 'unknown type'; ok = false;
    }
  } catch (e) { got = 'EXC ' + e.message; ok = false; }
  (byType[c.type] ||= { pass: 0, fail: 0 })[ok ? 'pass' : 'fail']++;
  if (ok) pass++; else fails.push({ name: c.name, got, expected: c.expected });
}
console.log(`fixtures: ${pass}/${fx.cases.length} pass`);
console.log(JSON.stringify(byType));
for (const f of fails.slice(0, 20)) console.log('FAIL', JSON.stringify(f));
process.exitCode = fails.length ? 1 : 0;
